## 00_paths.R - generated by new_project.ps1
## Always run analysis with the working directory set to the project root.
PROJ_ROOT <- normalizePath(".")

RAW_DIR   <- "data/raw"
PROC_DIR  <- "data/processed"
RES_DIR   <- "results"
FIG_DIR   <- file.path(RES_DIR, "figures")
TAB_DIR   <- file.path(RES_DIR, "tables")
OUT_DIR   <- "output"
LOG_DIR   <- "logs"

## RAW_DIR is READ ONLY: it holds junctions to the shared data catalog.
## Never write into RAW_DIR. Every output stays inside this project.
for (d in c(PROC_DIR, RES_DIR, FIG_DIR, TAB_DIR, OUT_DIR, LOG_DIR)) {
  dir.create(d, showWarnings = FALSE, recursive = TRUE)
}